args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?director ?directorLabel ?spouse ?spouseLabel WHERE {
  dbr:Bratuku_Teruvu dbo:director ?director .
  ?director dbo:spouse ?spouse .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER (lang(?spouseLabel) = "en") }
}

